csui.define('d2/utils/commands/vdoc.default.actions',[
  'nuc/lib/underscore',
  'csui/models/commands',
  // Load extra commands to be added to the common collection
  'csui-ext!d2/utils/commands/vdoc.default.actions'
], function (_, CommandCollection, extraCommands) {
  'use strict';

  var commands = new CommandCollection([]);//All default actions for VD will be loaded using extension

  if (extraCommands) {
    commands.add(
      _.chain(extraCommands)
        .flatten(true)
        .map(function (Command) {
          return new Command();
        })
        .value()
    );
  }

  return commands;

});
