csui.define('d2/dialogs/bws/create.bws.instance/properties/bws.multi.properties.view',[
    'require',
    'nuc/lib/jquery',
    'd2/dialogs/new.file/import/import.metadata.properties.view'
], function(require, $, ImportMetadataPropertiesView){

    var BwsMultiPropertiesView = ImportMetadataPropertiesView.extend({

        initViews: function(){
            let def = $.Deferred();
            csui.require([  'd2/controls/multi.item/multi.item.view',
                'd2/dialogs/bws/create.bws.instance/properties/bws.properties.view'

            ], (MultiItemView, BwsMetadataPropertiesView) =>{
                def.resolve({
                    MultiItemView:MultiItemView,
                    PropertiesView: BwsMetadataPropertiesView
                });
            });
            return def.promise();
        },
    });

    return BwsMultiPropertiesView;
});