csui.define('d2/commands/savedsearch/rename.search.category',['csui/utils/commands/inlineedit',
  'csui/utils/commandhelper'
], function (InlineEdit, CommandHelper) {
  'use strict';

  return InlineEdit.extend({
    defaults: {
      signature: 'D2-RenameSearchCategory',
      command_key: ['rename', 'Rename'],
      scope: 'single'
    },
    enabled: function (status/* , options*/) {
      var container = status.container,
        node = CommandHelper.getJustOneNode(status),
        enabled = (status.nodes && status.nodes.length === 1) && node.isCategoryNode() && InlineEdit.prototype.enabled.apply(this, arguments);

      if (enabled && container.isAvailablePublic()) {
        enabled = container.searchConfig && container.searchConfig.canCreatePublicSearch;
      }
      return enabled;
    }
  });
});