csui.define('d2/dialogs/digital.signature/supporting.document/table.columns',["nuc/lib/backbone",
  'i18n!d2/dialogs/digital.signature/supporting.document/impl/nls/lang'
], function (Backbone, lang) {

  var TableColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var TableColumnCollection = Backbone.Collection.extend({

    model: TableColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      return new TableColumnCollection(
        this.map(function (column) {
          return column.attributes;
        }));
    }

  });

  var tableColumns = new TableColumnCollection([
    {
      key: 'type',
      column_key: 'type',
      sequence: 2,
      definitions_order: 2,
      sort: false,
      repeating: false,
      title: lang.typeColumnHeader,
      type: -1,
      permanentColumn: true // don't wrap column due to responsiveness into details row
    },
    {
      key: 'name',
      column_key: 'name',
      sequence: 3,
      definitions_order: 3,
      sort: false,
      title: lang.nameColumnHeader,
      type: -1,
      widthFactor: 2,
      permanentColumn: true, // don't wrap column due to responsiveness into details row
    }
  ]);

  return tableColumns;

});
