csui.define('d2/controls/query.form/query.form.dialog',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'i18n',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'csui/controls/progressblocker/blocker',
  'csui/controls/mixins/layoutview.events.propagation/layoutview.events.propagation.mixin',
  'csui/utils/non-emptying.region/non-emptying.region',
  'd2/controls/query.form/query.form.panel.view',
  'd2/controls/query.form/query.form.model',
  'd2/controls/stepper.wizard/stepper.wizard.view',
  'hbs!d2/controls/query.form/impl/query.form.dialog',
  'i18n!d2/controls/query.form/impl/nls/lang',
  'css!d2/controls/query.form/impl/query.form.dialog',
  'csui/lib/binf/js/binf'
], function (_, $, i18n, Backbone, Marionette, BlockingView, LayoutViewEventsPropagationMixin,
             NonEmptyingRegion, QueryFormPanelView, QueryFormModel, StepperWizard,  template, lang
) {
  'use strict';

  function QueryFormDialog(options) {
    options || (options = {});
    this.options = options;
  }

  _.extend(QueryFormDialog.prototype, {

    show: function () {
      // return the show wizard promise
      // this promise is resolved either when wizard is shown or the dialog data fetch fails
      // thus the function invoking qdialog.show can perform additional logic on completion of this async operation
      return this._showWizard();
    },

    _createWizardSteps: function () {

      var
        step1 = {
          'id': 'queryformgeneral',
          'title': this.options.savedSearchName,
          'viewClass':QueryFormPanelView,
          'viewOptions':this.options,


          'buttons': [
            {
              id: 'next',
              toolTip: lang.search,
              label: lang.search,
              disabled: function() {
                return !this.isValidForm();
              },
              clickHandler: function(){
                this.executeQueryFormSearch();
              }
            }

          ]
        };

      var steparr = [];
      steparr.push(step1);
      return steparr;
    },

    _showWizard: function () {
      var self = this;
      return new Promise(function (resolve) {
        self.options.data = new QueryFormModel(self.options);
        var that = self;
        self.options.data.fetch().done(function () {
          that._steps = that._createWizardSteps();
          that._wizard = new StepperWizard({steps: that._steps, className: 'd2-queryform-modal', data: {}});
          that._wizard.show();
          that._wizard.on('wizard:shown', function () {
            // resolve showWizard promise on shown
            // binf modal will be called and backdrop will be set by then
            resolve();
          })
        }).fail(function () {
          // QF data fetch failed, still showWizard as an async function is completed
          // resolving the promise on data fetch error so that any other function relying on showWizard's completion can be resumed
          resolve();
        });
      });
    }

  });
  return QueryFormDialog;

});
