csui.define('d2/overrides/nuc/utils/connector',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/utils/log',
  'nuc/utils/messagehelper',
  'nuc/utils/errormessage',
  'nuc/utils/connector',
  'dctmw/utils/sw.utils',
  'dctmw/utils/utils'
], function (_, $, Backbone,  log, MessageHelper, Message, connector, serviceWorker, utils) {
  'use strict';

  const oldAssignTo = connector.prototype.assignTo;

  const oldExtendedAjax = connector.prototype.extendAjaxOptions;

  function isPerspectiveWideError(xhr, {ignoreHttp403 = false}) {
    if (xhr.status === 403 && ignoreHttp403 !== false) {
      return false;
    }
    return [0 /*Aborted, Offline, Connection refused*/, 403/*Forbidden*/].includes(xhr.status);
  }
  
  connector.prototype.assignTo = function (model) {
    const result = oldAssignTo.call(this, model),
      oldSync = model.sync,
      me = this;

    model.sync = function (method, model, options) {
      const syncResult = oldSync.call(this, method, model, options);
      syncResult.fail(function (xhr, txtStatus, error) {
        if (isPerspectiveWideError(xhr, options) && me.applyingErrorPerspective !== true) {
          if(me.context && me.context.rejectPerspective) {
            const perspectiveModel = new Backbone.Model(),
              listener = function (perspective, sourceModel) {
                if (sourceModel === perspectiveModel) {
                  me.applyingErrorPerspective = false;
                  me.context.off('change:perspective', listener, me.context);
                }
              };
            
            me.applyingErrorPerspective = true;
            me.context.listenTo(me.context, 'change:perspective', listener);
            me.context.rejectPerspective && me.context.rejectPerspective(perspectiveModel, utils.parseAjaxError(xhr, txtStatus, error, true));
          }
        }
      });
      return syncResult;
    };
    return result;
  }

  connector.prototype.extendAjaxOptions = function(options, restartRequest) {
    /************ related to service-worker support ***************/
    var beforeSend = options.beforeSend;
    options.beforeSend = function(xhr, settings) {
      if(settings.skipSWCache === true && serviceWorker.isEnabled()) {
        xhr.setRequestHeader('X-SW-NO-CACHE', true);
      }

      _.isFunction(beforeSend) && beforeSend(xhr, settings);
    };
    oldExtendedAjax.call(this, options,restartRequest);
    /************ related to service-worker support ***************/

    //Did this change as part of DTWO-80440. Will have to revisit once the REST returns the supported or installed locales
    if(options && options.headers && options.headers["Accept-Language"] ==='pt'){
      options.headers["Accept-Language"]='pt-BR'
    }

    return options
  }

  connector.prototype.reportError = function(request, error) {
    if (!error) {
      if (request instanceof Error) {
        error = request;
        request = undefined;
      } else {
        error = new Message.RequestErrorMessage(request);
      }
    }
    if(error?.message instanceof Message.RequestErrorMessage){
      error = error.message;
    }
    if (request && request.settings) {
      log.warn('{0} request to {1} failed:', request.settings.type, request.settings.url) && console.warn(log.last);
    }
    log.warn(error) && console.warn(log.last);
    MessageHelper.getInstance().addMessage(error.toString());
  }

});