csui.define('d2/overrides/csui/widgets/search.results/impl/search.results.header.title.view',[
  'require',
], function (require) {
  'use strict';

  csui.require([
    'csui/widgets/search.results/impl/search.results.header.title.view',
    'i18n!csui/widgets/search.results/impl/nls/lang'
  ], function (SearchResultsHeaderTitleView, lang) {
    /**
     *  OCTIM77IQ4865093 
     * NOTE: this code is from 25.2 where only result_title was present, and in latest, this title element is divided into two parts 
     * #resultsTitle, #titleText allowing for better customization. But this change has made less flexible for us to provide
     * custom result title as before which is "Search results for: " and just "Search results". The time when this was overriden, the logic in lib was
     * to replace the "Search results: " part from the resultsTitle and use that as titleText which does not work in our case.
     * So copied and kept the old code here, instead of directly updating the DOM with correct values ourself, for keeping track of this issue
     */
    SearchResultsHeaderTitleView.prototype._updateSearchResultsTitle = function () {
      var searchHeaderTitle, tooltipText;
      if (!!this.options.useCustomTitle && !!this.title) {
        this.ui.customSearchTitle.text(this.title);
        tooltipText = lang.searchResults + ': ' + this.title;
        searchHeaderTitle = lang.searchResults + ': ';
      } else {
        searchHeaderTitle = this.options.searchHeaderTitle;
        tooltipText = searchHeaderTitle;
      }
      this.ui.resultTitle.text(searchHeaderTitle);
      this.ui.resultTitle.parent().attr("title", tooltipText);
    }

  });
});