export function workerFunction() {
  let pollingId = null;
  let controller;

  async function doFetch({ url, options }) {
    try {
      const resp = await fetch(url, options);
      const data = await resp.json();

      if (resp.status === 401) {
        postMessage({ status: 'unauthorized' });
      } else if (resp.status >= 400) {
        postMessage({ status: 'error', response: data });
      } else {
        postMessage({ status: 'success', data });
      }
    } catch (err) {
      if (err.status === 401) {
        postMessage({ status: 'unauthorized' });
      } else {
        postMessage({ status: 'error', error: err.message });
      }
    }
  }

  function startPolling({ url, options, interval }) {
    if (pollingId !== null) return;
    pollingId = setInterval(() => {
      if (controller) {
        // Abort any previous ongoing request before starting a new one
        controller.abort();
      }
      controller = new AbortController();
      const signal = controller.signal;
      options.signal = signal;
      doFetch({ url, options})
    }, interval);
  }

  function stopPolling() {
    if (pollingId !== null) {
      if (controller) {
        // Abort any previous ongoing request
        controller.abort();
      }
      clearInterval(pollingId);
      pollingId = null;
    }
  }

  self.addEventListener('message', ({ data: { cmd, payload } }) => {
    if (cmd === 'START') {
      startPolling(payload);
    } else if (cmd === 'STOP') {
      stopPolling();
    }
  });
}
