csui.define('d2/controls/table/table.columns',["nuc/lib/backbone"], function (Backbone) {

  var TableColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var TableColumnCollection = Backbone.Collection.extend({

    model: TableColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      return new TableColumnCollection(this.map(function (column) {
        return column.attributes;
      }));
    }

  });

  return (new TableColumnCollection([{
    key: '_select',
    sequence: 1,
    permanentColumn: true, // don't wrap column due to responsiveness into details row,
    customization_not_resizeable: true,
    customization_resizeable: false,
    customization_pinned: true,
    customization_min_width: 32
  },{
    key: 'type',
    sequence: 2,
    permanentColumn: true, // don't wrap column due to responsiveness into details row
    customization_resizeable: false,
    customization_pinned: true,
    customization_min_width: 42
  }, {
    key: 'name',
    sequence: 3,
    permanentColumn: true, // don't wrap column due to responsiveness into details row
    customization_pinned: true,
    customization_width: 280,
    customization_min_width:200,
    customization_resize_span: 'reserved'
  }, {
    key: 'd2_version_label',
    sequence: 5,
    permanentColumn: true, // don't wrap column due to responsiveness into details row
    customization_pinned: true,
    customization_min_width: 160,
  }, {
    key: 'reserved',
    sequence: 6,
    permanentColumn: true, // don't wrap column due to responsiveness into details row
    customization_resizeable: false,
    customization_pinned: true,
    customization_min_width: 40
  },{
    key: 'd2_external_share',
    sequence: 7,
    permanentColumn: true, // don't wrap column due to responsiveness into details row
    customization_resizeable: false,
    customization_min_width: 32
  }, {
    key: 'wnd_comments',
    sequence: 900,
    noTitleInHeader: true,
    permanentColumn: true, // don't wrap column due to responsiveness into details row
    customization_resizeable: false,
    customization_min_width: 40
  }, {
    key: 'favorite',
    sequence: 910,
    noTitleInHeader: true,
    permanentColumn: true, // don't wrap column due to responsivenes into details row
    customization_resizeable: false
  }]));
});