csui.define('d2/overrides/csui/controls/listitem/listitemstandard.view',[
  'csui/controls/listitem/listitemstandard.view'
], function (StandardListItem) {
  'use strict';

  var proto = StandardListItem.prototype,
    oldOnShowInlineMenu = proto.onShowInlineMenu;

  proto.onShowInlineMenu = function () {
    this.model.setNonPromotedActionsOptions && this.model.setNonPromotedActionsOptions({
      isNonPromoted: false
    });
    oldOnShowInlineMenu.apply(this, arguments);
    //Overriding this method till CSUI fixes showing of just icon in case of one action instead of dropdown
    //In case one action is available, the action icon is shown instead of dropdown, focus on the icon in case of one action
    if (this._inlineMenuView) {
      this._inlineMenuView._focusFirstItem = function (event) {
        if (event.type === "keydown") {
          if (this.$el.find('.binf-dropdown-menu li:first a').length) {
            this.$el.find('.binf-dropdown-menu li:first a').trigger("focus");
          } else {
            this.$el.find('.tile-nav li a').trigger('focus');
          }
        }
      };

    }
  };
});