import $ from 'nuc/lib/jquery'
import TabLinksExtScrollMixin from 'smart/controls/tab.panel/tab.links.ext.scroll.mixin';
const origShowAndHideNavigationButtons = TabLinksExtScrollMixin._showHideNavigationButtons;


/**
 * Overridden this function as there was mismatch between the collection title(title) and tablink title(domTitle) in case of tab is hidden.
 * Have returned the proper index so it helps in setting the header accordingly.
 */
TabLinksExtScrollMixin._findTabIndexByID = function (tabID) {
    var formModel = null;
    var tabs = this.tablinksToolbar && this.tablinksToolbar.find(this.tabsSelector);
    let filteredItems = this.collection.filter(model => !(model.get("hidden") || model.get("options")?.hideTab));
    if (tabs) {
        var i;
        for (i = 0; i < tabs.length; i++) {
            var href = $(tabs[i]).find(">a").attr("href");
            let domTitle = $(tabs[i]).find(">a").attr("title");
            let title = filteredItems[i]?.attributes?.title;
            href[0] === "#" && (href = href.substr(1));
            if (tabID === href && domTitle === title) {
                formModel = filteredItems[i];
                break;
            }
        }
    }
    return this.collection.indexOf(formModel);
}

TabLinksExtScrollMixin._showHideNavigationButtons = function(){

    function isAllTabChildrenAreHidden(){
        return (this.isTabVisible(this.tabLinksBarChildren[0]) &&
            this.isTabVisible(this.tabLinksBarChildren[this.tabLinksBarChildren.length - 1])) === false;
    }

    if (this.options?.suppressSpyScroll) {
        if (this.options.hideTabLinkConversion) {
            if (isAllTabChildrenAreHidden.bind(this)) {
                this.leftToolbar && this.leftToolbar.addClass('binf-hidden');
                this.rightToolbar && this.rightToolbar.addClass('binf-hidden');
            }
        } else {
            origShowAndHideNavigationButtons.call(this, arguments);
        }
    } else {
        origShowAndHideNavigationButtons.call(this, arguments);
    }

}
