csui.define('d2/server.adaptors/models/esoc/commentscollection.model.mixin',[
  "nuc/lib/jquery",
  "nuc/lib/backbone",
  "nuc/lib/underscore",
  'nuc/utils/url',
  "nuc/utils/base",
  'dctmw/utils/rest.resources',
  'd2/utils/rest.linkrels',
  'd2/server.adaptors/converters/comment',
  'd2/server.adaptors/models/esoc/comments.utils'
], function ($, Backbone, _, Url, Base, RestResources,
             RestLinkrels, commentConverter, CommentsUtils) {
  'use strict';

  return {
    mixin: function (prototype) {
      var superSyncMethod = prototype.sync;

      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },
        base: Base,
        url: function () {
          var url = RestLinkrels.getLink(this.currentNodeModel.get('links'),
            RestLinkrels.COMMENTS);
          if (url) {
            url = Url.appendQuery(url,
              Url.combineQueryString({'inline': true, 'include-total': true}));
            return url;
          }
        },
        fetch: function (/*options*/) {
          Backbone.Collection.prototype.fetch.apply(this, arguments);
        },
        sync: function (method, collection, options) {
          return superSyncMethod.call(this, method, collection, options).done(function (/*response*/) {
            if (collection.length > 0) {
              CommentsUtils.fetchTotalReplies(collection);
            }
          }.bind(this));
        },
        parse: function (response) {

          // todo: Why esoc does this?
          //delete this.defaults.params[this.util.commonUtil.globalConstants.SINCE_ID];
          //return this.parseCommentsCollectionResponse(returnData);

          if (response.entries) {
            return _.map(response.entries.reverse(), function (entry) {
              return commentConverter.convertComment(entry);
            });
          }
        },

        getCurrentUserInfo: function () {
          var currentUser = RestResources.getCurrentUser();
          return {
            first_name: currentUser.get('first_name'),
            last_name: currentUser.get('last_name'),
            name: currentUser.get('display_name'),
            photo_id: currentUser.get('photo_url'),
            profile_image_url: currentUser.get('photo_url'),
            user_id: currentUser.get('id')
          };
        },

        getConfigSettings: function () {
          return {
            auditProfilePhotoFetch: "off",
            disableCommentsInWorkflowVolume: "off",
            disablePhotoCache: "off",
            disablePulseFromHere: "off",
            exnodetypeitems: "",
            feedGrowToMax: "60",
            feedsAutoRefreshWait: 10000,
            masterSwitchEnabled: true,
            maxMessageLength: 1000,
            maxNumOfEntries: 60,
            msgMaxLen: "1000",
            numConnects: "20",
            refreshInterval: "10",
            timelineItems: "20",
            visibility: "on"
          };
        }

      });
    }

  };

});
