csui.define('d2/widgets/navigation.header/controls/search/search.options.node.matcher',[
  'nuc/lib/underscore',
  'nuc/models/mixins/rules.matching/rules.matching.mixin',
  'd2/utils/constants'
], function (_, RulesMatchingMixin, constants) {
  'use strict';

  var rule_NodeEligileForNodeScope = {
    and: {
      not: {
        equals: {
          id: null
        }
      },
      or: [
        {
          equals: {
            type: constants.Types.CABINET
          }
        },
        {
          equals: {
            type: constants.Types.FOLDER
          }
        },
        {
          equals: {
            type: constants.Types.BWS
          }
        }
      ]
    }
  };

  var nodeMatcher = {
    isEligibleForNodeScope: function (nodeModel) {
      return this.matchRules(nodeModel, rule_NodeEligileForNodeScope);
    }
  };

  RulesMatchingMixin.mixin(nodeMatcher);
  return nodeMatcher;
});